package com.example.starter.ros.dto;

import java.util.List;

/**
 * 热更新事务结果。
 *
 * @param transactionId 事务 ID
 * @param committed     是否原子提交
 * @param idempotentReplay true 表示该事务此前已完成，本次直接返回原结果
 * @param nodeResults   各节点校验/应用结果
 */
public record HotUpdateResponse(
        String transactionId,
        boolean committed,
        boolean idempotentReplay,
        List<NodeResult> nodeResults
) {
    /**
     * 单个节点的处理结果。
     *
     * @param node    节点名
     * @param status  ACCEPTED / REJECTED / VERSION_CONFLICT / TIMEOUT / ERROR
     * @param reason  拒绝或失败原因（成功时为 null）
     * @param version 提交后该节点的新版本（未提交时为当前/期望版本信息，可能为 null）
     */
    public record NodeResult(
            String node,
            String status,
            String reason,
            Long version
    ) {
        public static final String ACCEPTED = "ACCEPTED";
        public static final String REJECTED = "REJECTED";
        public static final String VERSION_CONFLICT = "VERSION_CONFLICT";
        public static final String TIMEOUT = "TIMEOUT";
        public static final String ERROR = "ERROR";
    }
}

package com.example.starter.ros.dto;

/**
 * 参数事件流中的一条事件，游标在全库范围内单调递增。
 *
 * @param cursor        单调游标，从 1 开始
 * @param transactionId 产生该事件的事务 ID
 * @param type          COMMITTED / REJECTED_PRECHECK / ROLLBACK 等
 * @param node          关联节点（事务级事件可含汇总信息，此处为主要目标节点）
 * @param payload       事件内容（JSON 字符串）
 * @param createdAtMs   事件创建时间（毫秒，Asia/Shanghai 业务时区）
 */
public record ParamEvent(
        long cursor,
        String transactionId,
        String type,
        String node,
        String payload,
        long createdAtMs
) {
    public static final String TYPE_COMMITTED = "COMMITTED";
}

