                            rs.getString("value"));
                }, node);
        return result;
    }

    /** 全量列表（管理用途），每行含 transactionId/node/group/name/value。 */
    public List<Map<String, Object>> findAll() {
        return jdbc.query("SELECT transaction_id, node, group_name, name, value, created_at"
                        + " FROM ros_pending_restart ORDER BY id",
