                    row.put("node", rs.getString("node"));
                    row.put("group", rs.getString("group_name"));
                    row.put("name", rs.getString("name"));
                    row.put("value", rs.getString("value"));
                    row.put("createdAtMs", rs.getLong("created_at"));
                    return row;
                });
    }
}

